function ROUND_TRIP(length n, step, x):
    state <- x
    for i from 0 to n-1:
        state <- step(i mod n, state)
    return state

function CONSISTENT_HISTORIES(length n, step, states X):
    histories <- empty list
    for each x in X:
        if ROUND_TRIP(n, step, x) = x:      # fixed point
            period <- [x]
            s <- x
            for i from 0 to n-2:
                s <- step(i mod n, s)
                append s to period
            append period to histories
    return histories

function IS_SELF_CONSISTENT(n, step, X):
    return CONSISTENT_HISTORIES(n, step, X) is non-empty

function MINIMAL_CONSISTENT_REPETITION(round_trip R, states X):
    if X is empty: return NONE
    for k from 1 to |X|:
        for each x in X:
            y <- x
            repeat k times: y <- R(y)
            if y = x: return k       # R^k fixes x => L^k consistent
    return NONE                      # unreachable on finite X
